insert into public.projects (id, owner_id, title, description, category, state, help, reach, lat, lng, photo_url, created_at, updated_at) values
  ('ea100000-0000-4000-8000-000000000001', 'e1000000-0000-4000-8000-000000000001', 'Saturday cleanup at Cheesman Park', 'One hour, gloves and bags provided, coffee after at the Tattered Cover steps. The park is ours and it looks like nobody''s. Twelve people would make it spotless monthly.', 'outdoors', 'active', 'local', 'neighborhood', 39.740056, -104.968969, null, now() - interval '31 days 14 hours', now() - interval '30 days'),
  ('ea100000-0000-4000-8000-000000000002', 'e1000000-0000-4000-8000-000000000012', 'Community fridge near the Tattered Cover steps', 'The café agreed to host a community fridge on their wall — surplus food in, anyone takes what they need. Need help building the shelter box and a small rota to keep it clean.', 'giving', 'idea', 'local', 'neighborhood', null, null, null, now() - interval '5 days 11 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000003', 'e1000000-0000-4000-8000-000000000007', 'Fix the wobbly benches in Highland Park', 'Five benches, all loose, one actually dangerous. Wood, screws, one afternoon. The parks office says if we fix them to spec they''ll sign it off.', 'home', 'active', 'local', 'neighborhood', 39.733620, -104.970546, null, now() - interval '35 days 13 hours', now() - interval '34 days'),
  ('ea100000-0000-4000-8000-000000000004', 'e1000000-0000-4000-8000-000000000010', 'Teach seniors to video-call their grandkids', 'One hour, one senior, one phone. The community center gives us the room. Patient people wanted; tech skills optional, kindness mandatory.', 'learning', 'completed', 'local', 'neighborhood', 39.757838, -105.010234, '/photos/contact-tree.jpg', now() - interval '10 days 2 hours', now() - interval '3 days'),
  ('ea100000-0000-4000-8000-000000000005', 'e1000000-0000-4000-8000-000000000005', 'Free bike repair Saturdays at the Highland Bridge', 'I fix bikes in front of my garage, first Saturday every month. Bring your bike, learn to do it yourself. Another pair of greasy hands would double what we handle.', 'community', 'idea', 'local', 'neighborhood', 39.730600, -104.990286, null, now() - interval '13 days 13 hours', now() - interval '12 days'),
  ('ea100000-0000-4000-8000-000000000006', 'e1000000-0000-4000-8000-000000000016', 'Translate the city''s recycling rules into six languages', 'The rules are only in English and half the block guesses wrong. I have the official text; I need native speakers — anywhere — for Spanish, Vietnamese, Arabic, Polish, Tagalog and Amharic.', 'community', 'active', 'remote', 'global', null, null, null, now() - interval '4 days 0 hours', now() - interval '3 days'),
  ('ea100000-0000-4000-8000-000000000007', 'e1000000-0000-4000-8000-000000000017', 'Seed and cutting swap on Duval Street', 'Everyone''s windowsill basil dies alone. Twice a month we swap seeds, cuttings and advice outside the hardware store. Need a second table and someone who labels legibly.', 'outdoors', 'active', 'local', 'neighborhood', null, null, null, now() - interval '18 days 10 hours', now() - interval '17 days'),
  ('ea100000-0000-4000-8000-000000000008', 'e1000000-0000-4000-8000-000000000028', 'Couch-to-5k around Shipe Park, beginners only', 'If you can''t run 400 meters, you''re exactly who this is for. Tuesdays and Saturdays, slower than you think, nobody left behind.', 'fitness', 'idea', 'local', 'neighborhood', 30.313645, -97.722271, '/photos/costumes.jpg', now() - interval '27 days 19 hours', now() - interval '26 days'),
  ('ea100000-0000-4000-8000-000000000009', 'e1000000-0000-4000-8000-000000000023', 'Little free pantry on East 6th Street', 'Like a little free library but for cans and pasta. I''ll build the box — I need a host with a visible fence and three or four people to check it weekly.', 'giving', 'active', 'local', 'neighborhood', null, null, null, now() - interval '23 days 20 hours', now() - interval '22 days'),
  ('ea100000-0000-4000-8000-000000000010', 'e1000000-0000-4000-8000-000000000026', 'After-school homework club', 'Two retired teachers already in. We take any kid, any subject, Monday to Wednesday at the rec center. Could use two more adults and someone who bakes.', 'learning', 'completed', 'local', 'neighborhood', 30.303268, -97.729005, null, now() - interval '4 days 10 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000011', 'e1000000-0000-4000-8000-000000000021', 'Mural for the underpass by the Shipe Park pool', 'It''s grey, it''s grim, and every kid walks through it daily. Provisional blessing from the alderman and two art students — we need painters of any level and someone to charm a paint shop.', 'arts', 'idea', 'both', 'city', null, null, null, now() - interval '25 days 18 hours', now() - interval '24 days'),
  ('ea100000-0000-4000-8000-000000000012', 'e1000000-0000-4000-8000-000000000032', 'Dog-walking pool for shift workers', 'Nurses and drivers can''t walk dogs at 2pm. We match dogs with neighbors who''d love a walk buddy without owning one. Five reliable walkers to start.', 'social', 'active', 'local', 'neighborhood', 30.308896, -97.721045, '/photos/midnight-football.jpg', now() - interval '16 days 2 hours', now() - interval '15 days'),
  ('ea100000-0000-4000-8000-000000000013', 'e1000000-0000-4000-8000-000000000033', 'Translate the city''s recycling rules into six languages', 'The rules are only in English and half the block guesses wrong. I have the official text; I need native speakers — anywhere — for Spanish, Vietnamese, Arabic, Polish, Tagalog and Amharic.', 'community', 'active', 'remote', 'global', null, null, null, now() - interval '41 days 0 hours', now() - interval '40 days'),
  ('ea100000-0000-4000-8000-000000000014', 'e1000000-0000-4000-8000-000000000044', 'Map every accessible entrance along Abrams Road', 'Wheelchair users shouldn''t need luck to find a way in. We survey shops door by door and publish a free map. Walkers and wheelers welcome; a data person would be gold.', 'community', 'idea', 'both', 'city', 32.815567, -96.744957, null, now() - interval '25 days 15 hours', now() - interval '24 days'),
  ('ea100000-0000-4000-8000-000000000015', 'e1000000-0000-4000-8000-000000000039', 'Podcast about ordinary neighbors doing great things', 'Every episode: one neighbor, one story, thirty minutes. I have mics and enthusiasm; I need an editor (remote is fine) and introverts willing to be interviewed.', 'arts', 'active', 'remote', 'global', 32.746152, -96.837301, null, now() - interval '23 days 7 hours', now() - interval '22 days'),
  ('ea100000-0000-4000-8000-000000000016', 'e1000000-0000-4000-8000-000000000042', 'Repair café at the Lakewood library — bring your broken things', 'Toasters, trousers, tablets: we fix instead of toss, last Sunday monthly. Have menders for textiles and wood; need an electronics person and a greeter.', 'giving', 'completed', 'local', 'neighborhood', null, null, '/photos/air-quality.jpg', now() - interval '4 days 1 hours', now() - interval '1 days'),
  ('ea100000-0000-4000-8000-000000000017', 'e1000000-0000-4000-8000-000000000037', 'Oral history of Abrams Road, before it''s gone', 'Mrs. Okafor is 91 and remembers the street when it had a dairy. Recording the elders'' stories before they disappear. Need an interviewer and someone to digitize old photos.', 'learning', 'idea', 'both', 'neighborhood', 32.749489, -96.823818, null, now() - interval '12 days 18 hours', now() - interval '11 days'),
  ('ea100000-0000-4000-8000-000000000018', 'e1000000-0000-4000-8000-000000000048', 'Solar panels for the rec center roof', 'The quote is doable if we self-organize the paperwork and half the labor. An electrician, a grant veteran and a few Saturday bodies gets it done.', 'venture', 'active', 'both', 'city', null, null, null, now() - interval '24 days 17 hours', now() - interval '23 days'),
  ('ea100000-0000-4000-8000-000000000019', 'e1000000-0000-4000-8000-000000000049', 'Dog-walking pool for shift workers', 'Nurses and drivers can''t walk dogs at 2pm. We match dogs with neighbors who''d love a walk buddy without owning one. Five reliable walkers to start.', 'social', 'active', 'local', 'neighborhood', 29.792273, -95.394175, null, now() - interval '33 days 13 hours', now() - interval '32 days'),
  ('ea100000-0000-4000-8000-000000000020', 'e1000000-0000-4000-8000-000000000060', 'Community compost behind Donovan Park', 'Three bays, proper signage, no rats (promise). The garden association is in. Need builders for a weekend and households willing to fill it right.', 'outdoors', 'idea', 'local', 'neighborhood', 29.742611, -95.384239, '/photos/window-boxes.jpg', now() - interval '25 days 10 hours', now() - interval '24 days'),
  ('ea100000-0000-4000-8000-000000000021', 'e1000000-0000-4000-8000-000000000055', 'Beginner-friendly community choir', 'No auditions, no sheet-music snobbery. Wednesday nights at the church hall. We have a conductor; we need singers who think they can''t sing and someone to run the socials.', 'arts', 'active', 'local', 'city', 29.787240, -95.408498, null, now() - interval '6 days 7 hours', now() - interval '5 days'),
  ('ea100000-0000-4000-8000-000000000022', 'e1000000-0000-4000-8000-000000000058', 'Friday night pickup basketball at Menil Park', 'The court is lit and empty every night. Friday evening run, all levels, zero attitude. Need one more organizer so it survives holidays.', 'fitness', 'completed', 'local', 'neighborhood', 29.747569, -95.385805, null, now() - interval '12 days 20 hours', now() - interval '1 days'),
  ('ea100000-0000-4000-8000-000000000023', 'e1000000-0000-4000-8000-000000000053', 'Block emergency contact tree', 'When the water main burst nobody knew who to check on. A simple phone tree, block by block, tested twice a year. One volunteer per block — that''s it.', 'community', 'idea', 'local', 'neighborhood', 29.791214, -95.388307, null, now() - interval '6 days 8 hours', now() - interval '5 days'),
  ('ea100000-0000-4000-8000-000000000024', 'e1000000-0000-4000-8000-000000000064', 'Window-box challenge for Westheimer Road', 'A concrete canyon. Fifty window boxes would change it completely. Bulk soil and seedlings negotiated; need neighbors to claim a window each.', 'outdoors', 'active', 'local', 'neighborhood', 29.738187, -95.384654, '/photos/solar-roof.jpg', now() - interval '31 days 7 hours', now() - interval '30 days'),
  ('ea100000-0000-4000-8000-000000000025', 'e1000000-0000-4000-8000-000000000065', 'Solar panels for the rec center roof', 'The quote is doable if we self-organize the paperwork and half the labor. An electrician, a grant veteran and a few Saturday bodies gets it done.', 'venture', 'active', 'both', 'city', 33.451032, -112.073111, null, now() - interval '11 days 2 hours', now() - interval '10 days'),
  ('ea100000-0000-4000-8000-000000000026', 'e1000000-0000-4000-8000-000000000076', 'Sew the school-play costumes together', 'The school play needs 30 costumes and has budget for 5. If eight people who can thread a machine give two evenings, every kid gets a costume that fits.', 'home', 'idea', 'local', 'neighborhood', 33.509377, -111.975827, null, now() - interval '41 days 10 hours', now() - interval '40 days'),
  ('ea100000-0000-4000-8000-000000000027', 'e1000000-0000-4000-8000-000000000071', 'Plain-language dashboard for the city''s air sensors', 'The sensors exist, the data''s public, nobody can read it. Building a dashboard anyone understands. Need a frontend dev and a data-viz person — remote welcome.', 'venture', 'active', 'remote', 'global', 33.463094, -112.068934, null, now() - interval '26 days 15 hours', now() - interval '25 days'),
  ('ea100000-0000-4000-8000-000000000028', 'e1000000-0000-4000-8000-000000000074', 'Learn-to-swim scholarships at the city pool', 'Every summer kids drown who never had lessons. The pool offered discounted slots if we organize sign-ups and sponsors. Need organizers and a treasurer type.', 'giving', 'completed', 'both', 'city', null, null, '/photos/choir.jpg', now() - interval '34 days 6 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000029', 'e1000000-0000-4000-8000-000000000069', 'Tool library in the garage on Indian School Road', 'Forty drills on one block and each gets used twice a year. Lending shelf, paper notebook, Saturday hours. Need a second key-holder and a label maker.', 'giving', 'idea', 'local', 'neighborhood', 33.459749, -112.076832, null, now() - interval '10 days 15 hours', now() - interval '9 days'),
  ('ea100000-0000-4000-8000-000000000030', 'e1000000-0000-4000-8000-000000000080', 'Pop-up open mic at the corner café', 'Poems, songs, that joke you keep telling. Third Thursday. The café''s in; we need a host and a sound person.', 'arts', 'active', 'local', 'neighborhood', 33.511495, -111.976116, null, now() - interval '6 days 15 hours', now() - interval '5 days'),
  ('ea100000-0000-4000-8000-000000000031', 'e1000000-0000-4000-8000-000000000081', 'Window-box challenge for York Boulevard', 'A concrete canyon. Fifty window boxes would change it completely. Bulk soil and seedlings negotiated; need neighbors to claim a window each.', 'outdoors', 'active', 'local', 'neighborhood', 34.082486, -118.270465, null, now() - interval '39 days 9 hours', now() - interval '38 days'),
  ('ea100000-0000-4000-8000-000000000032', 'e1000000-0000-4000-8000-000000000092', 'Potluck under the trees at Silver Lake Meadow', 'Once a month, one dish each, long tables, no speeches. Need two people to haul tables and someone to keep the sign-up sheet honest.', 'food', 'idea', 'local', 'neighborhood', 34.116993, -118.191722, '/photos/swim-lessons.jpg', now() - interval '17 days 10 hours', now() - interval '16 days'),
  ('ea100000-0000-4000-8000-000000000033', 'e1000000-0000-4000-8000-000000000087', 'Sunday morning tai chi at the reservoir path', 'Slow, outdoors, free. A retired instructor leads; we need a backup leader and someone to bring the speaker.', 'fitness', 'active', 'local', 'neighborhood', 34.091349, -118.281152, null, now() - interval '30 days 3 hours', now() - interval '29 days'),
  ('ea100000-0000-4000-8000-000000000034', 'e1000000-0000-4000-8000-000000000090', 'Chess in Silver Lake Meadow on Saturdays', 'Boards on the picnic tables, all ages, all levels. Need a few sets and someone patient with eight-year-olds.', 'games', 'completed', 'local', 'neighborhood', 34.103726, -118.190402, null, now() - interval '5 days 0 hours', now() - interval '2 days'),
  ('ea100000-0000-4000-8000-000000000035', 'e1000000-0000-4000-8000-000000000085', 'Welcome kits for new neighbors on Sunset Boulevard', 'A map, a list of the good shops, two cookies. Hand-delivered by someone who lives here. Need writers, bakers and a walker.', 'social', 'idea', 'local', 'neighborhood', 34.093150, -118.280902, null, now() - interval '32 days 10 hours', now() - interval '31 days'),
  ('ea100000-0000-4000-8000-000000000036', 'e1000000-0000-4000-8000-000000000096', 'Start-up clinic for neighbors with a side business', 'Two accountants and a lawyer on the block, one evening a month, free questions. Need a room and someone to keep the list.', 'venture', 'active', 'local', 'city', 34.118080, -118.188320, '/photos/park-cleanup.jpg', now() - interval '20 days 6 hours', now() - interval '19 days'),
  ('ea100000-0000-4000-8000-000000000037', 'e1000000-0000-4000-8000-000000000097', 'Pop-up open mic at the corner café', 'Poems, songs, that joke you keep telling. Third Thursday. The café''s in; we need a host and a sound person.', 'arts', 'active', 'local', 'neighborhood', 32.740279, -117.138102, null, now() - interval '12 days 8 hours', now() - interval '11 days'),
  ('ea100000-0000-4000-8000-000000000038', 'e1000000-0000-4000-8000-000000000108', 'Neighborhood bulk buy of good coffee', 'Fifteen households, one roaster, one delivery. Cheaper and better. Need a spreadsheet person and a porch for drop-offs.', 'food', 'idea', 'local', 'neighborhood', 32.742403, -117.255886, null, now() - interval '34 days 1 hours', now() - interval '33 days'),
  ('ea100000-0000-4000-8000-000000000039', 'e1000000-0000-4000-8000-000000000103', 'Bird walks in Bird Park, dawn, slow', 'An hour, binoculars shared, coffee after. A birder leads; we need a second pair of eyes and a flask.', 'outdoors', 'active', 'local', 'neighborhood', 32.745445, -117.126199, null, now() - interval '16 days 20 hours', now() - interval '15 days'),
  ('ea100000-0000-4000-8000-000000000040', 'e1000000-0000-4000-8000-000000000106', 'Saturday cleanup at Bird Park', 'One hour, gloves and bags provided, coffee after at the North Park sign. The park is ours and it looks like nobody''s. Twelve people would make it spotless monthly.', 'outdoors', 'completed', 'local', 'neighborhood', 32.745506, -117.256438, '/photos/contact-tree.jpg', now() - interval '7 days 19 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000041', 'e1000000-0000-4000-8000-000000000101', 'Community fridge near Dog Beach', 'The café agreed to host a community fridge on their wall — surplus food in, anyone takes what they need. Need help building the shelter box and a small rota to keep it clean.', 'giving', 'idea', 'local', 'neighborhood', 32.747228, -117.131665, null, now() - interval '27 days 4 hours', now() - interval '26 days'),
  ('ea100000-0000-4000-8000-000000000042', 'e1000000-0000-4000-8000-000000000112', 'Fix the wobbly benches in Robb Field', 'Five benches, all loose, one actually dangerous. Wood, screws, one afternoon. The parks office says if we fix them to spec they''ll sign it off.', 'home', 'active', 'local', 'neighborhood', 32.745462, -117.252757, null, now() - interval '43 days 3 hours', now() - interval '42 days'),
