  ('ea100000-0000-4000-8000-000000000044', 'e1000000-0000-4000-8000-000000000124', 'Repaint the faded crosswalks on Valencia Street', 'Both crossings by the school have almost disappeared. The city says ''next year''. One weekend, proper road paint, done. Need steady hands and someone with a pressure washer.', 'community', 'idea', 'local', 'neighborhood', 37.765397, -122.472656, '/photos/costumes.jpg', now() - interval '5 days 7 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000045', 'e1000000-0000-4000-8000-000000000119', 'Weekly board game night', 'The library lets us use the back room every Thursday. Four boxes of games, more welcome. Come play — and I could use a co-host so it survives my flu.', 'games', 'active', 'local', 'neighborhood', null, null, null, now() - interval '17 days 8 hours', now() - interval '16 days'),
