  ('ea100000-0000-4000-8000-000000000053', 'e1000000-0000-4000-8000-000000000133', 'Map every accessible entrance along Fremont Avenue', 'Wheelchair users shouldn''t need luck to find a way in. We survey shops door by door and publish a free map. Walkers and wheelers welcome; a data person would be gold.', 'community', 'idea', 'both', 'city', 47.673684, -122.380525, null, now() - interval '33 days 16 hours', now() - interval '32 days'),
  ('ea100000-0000-4000-8000-000000000054', 'e1000000-0000-4000-8000-000000000144', 'Podcast about ordinary neighbors doing great things', 'Every episode: one neighbor, one story, thirty minutes. I have mics and enthusiasm; I need an editor (remote is fine) and introverts willing to be interviewed.', 'arts', 'active', 'remote', 'global', null, null, null, now() - interval '21 days 7 hours', now() - interval '20 days'),
  ('ea100000-0000-4000-8000-000000000055', 'e1000000-0000-4000-8000-000000000145', 'Little free pantry on 18th Street', 'Like a little free library but for cans and pasta. I''ll build the box — I need a host with a visible fence and three or four people to check it weekly.', 'giving', 'active', 'local', 'neighborhood', 41.927061, -87.700502, null, now() - interval '41 days 18 hours', now() - interval '40 days'),
  ('ea100000-0000-4000-8000-000000000056', 'e1000000-0000-4000-8000-000000000156', 'After-school homework club', 'Two retired teachers already in. We take any kid, any subject, Monday to Wednesday at the rec center. Could use two more adults and someone who bakes.', 'learning', 'idea', 'local', 'neighborhood', null, null, '/photos/window-boxes.jpg', now() - interval '8 days 19 hours', now() - interval '7 days'),
  ('ea100000-0000-4000-8000-000000000057', 'e1000000-0000-4000-8000-000000000151', 'Mural for the underpass by the Logan Square monument', 'It''s grey, it''s grim, and every kid walks through it daily. Provisional blessing from the alderman and two art students — we need painters of any level and someone to charm a paint shop.', 'arts', 'active', 'both', 'city', 41.926059, -87.702079, null, now() - interval '6 days 9 hours', now() - interval '5 days'),
  ('ea100000-0000-4000-8000-000000000058', 'e1000000-0000-4000-8000-000000000154', 'Dog-walking pool for shift workers', 'Nurses and drivers can''t walk dogs at 2pm. We match dogs with neighbors who''d love a walk buddy without owning one. Five reliable walkers to start.', 'social', 'completed', 'local', 'neighborhood', 41.853711, -87.659767, null, now() - interval '15 days 4 hours', now() - interval '1 days'),
  ('ea100000-0000-4000-8000-000000000059', 'e1000000-0000-4000-8000-000000000149', 'Community compost behind Palmer Square', 'Three bays, proper signage, no rats (promise). The garden association is in. Need builders for a weekend and households willing to fill it right.', 'outdoors', 'idea', 'local', 'neighborhood', 41.923277, -87.717754, null, now() - interval '40 days 7 hours', now() - interval '39 days'),
  ('ea100000-0000-4000-8000-000000000060', 'e1000000-0000-4000-8000-000000000160', 'Beginner-friendly community choir', 'No auditions, no sheet-music snobbery. Wednesday nights at the church hall. We have a conductor; we need singers who think they can''t sing and someone to run the socials.', 'arts', 'active', 'local', 'city', 41.862695, -87.660180, '/photos/solar-roof.jpg', now() - interval '33 days 9 hours', now() - interval '32 days'),
  ('ea100000-0000-4000-8000-000000000061', 'e1000000-0000-4000-8000-000000000161', 'Podcast about ordinary neighbors doing great things', 'Every episode: one neighbor, one story, thirty minutes. I have mics and enthusiasm; I need an editor (remote is fine) and introverts willing to be interviewed.', 'arts', 'active', 'remote', 'global', null, null, null, now() - interval '13 days 8 hours', now() - interval '12 days'),
  ('ea100000-0000-4000-8000-000000000062', 'e1000000-0000-4000-8000-000000000172', 'Repair café at the Grand Army Plaza market — bring your broken things', 'Toasters, trousers, tablets: we fix instead of toss, last Sunday monthly. Have menders for textiles and wood; need an electronics person and a greeter.', 'giving', 'idea', 'local', 'neighborhood', 40.675924, -73.979259, null, now() - interval '5 days 14 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000063', 'e1000000-0000-4000-8000-000000000167', 'Oral history of 5th Avenue, before it''s gone', 'Mrs. Okafor is 91 and remembers the street when it had a dairy. Recording the elders'' stories before they disappear. Need an interviewer and someone to digitize old photos.', 'learning', 'active', 'both', 'neighborhood', 40.765949, -73.912838, null, now() - interval '15 days 12 hours', now() - interval '14 days'),
  ('ea100000-0000-4000-8000-000000000064', 'e1000000-0000-4000-8000-000000000170', 'Solar panels for the rec center roof', 'The quote is doable if we self-organize the paperwork and half the labor. An electrician, a grant veteran and a few Saturday bodies gets it done.', 'venture', 'completed', 'both', 'city', 40.676741, -73.984854, '/photos/choir.jpg', now() - interval '40 days 20 hours', now() - interval '4 days'),
  ('ea100000-0000-4000-8000-000000000065', 'e1000000-0000-4000-8000-000000000165', 'Sew the school-play costumes together', 'The school play needs 30 costumes and has budget for 5. If eight people who can thread a machine give two evenings, every kid gets a costume that fits.', 'home', 'idea', 'local', 'neighborhood', 40.762753, -73.928596, null, now() - interval '27 days 8 hours', now() - interval '26 days'),
  ('ea100000-0000-4000-8000-000000000066', 'e1000000-0000-4000-8000-000000000176', 'Plain-language dashboard for the city''s air sensors', 'The sensors exist, the data''s public, nobody can read it. Building a dashboard anyone understands. Need a frontend dev and a data-viz person — remote welcome.', 'venture', 'active', 'remote', 'global', null, null, null, now() - interval '7 days 0 hours', now() - interval '6 days'),
  ('ea100000-0000-4000-8000-000000000067', 'e1000000-0000-4000-8000-000000000177', 'Beginner-friendly community choir', 'No auditions, no sheet-music snobbery. Wednesday nights at the church hall. We have a conductor; we need singers who think they can''t sing and someone to run the socials.', 'arts', 'active', 'local', 'city', 33.764438, -84.350903, null, now() - interval '45 days 15 hours', now() - interval '44 days'),
  ('ea100000-0000-4000-8000-000000000068', 'e1000000-0000-4000-8000-000000000188', 'Friday night pickup basketball at Freedom Park', 'The court is lit and empty every night. Friday evening run, all levels, zero attitude. Need one more organizer so it survives holidays.', 'fitness', 'idea', 'local', 'neighborhood', 33.733493, -84.347063, '/photos/swim-lessons.jpg', now() - interval '21 days 18 hours', now() - interval '20 days'),
  ('ea100000-0000-4000-8000-000000000069', 'e1000000-0000-4000-8000-000000000183', 'Block emergency contact tree', 'When the water main burst nobody knew who to check on. A simple phone tree, block by block, tested twice a year. One volunteer per block — that''s it.', 'community', 'active', 'local', 'neighborhood', null, null, null, now() - interval '10 days 8 hours', now() - interval '9 days'),
  ('ea100000-0000-4000-8000-000000000070', 'e1000000-0000-4000-8000-000000000186', 'Window-box challenge for Edgewood Avenue', 'A concrete canyon. Fifty window boxes would change it completely. Bulk soil and seedlings negotiated; need neighbors to claim a window each.', 'outdoors', 'completed', 'local', 'neighborhood', null, null, null, now() - interval '24 days 15 hours', now() - interval '2 days'),
  ('ea100000-0000-4000-8000-000000000071', 'e1000000-0000-4000-8000-000000000181', 'Potluck under the trees at Freedom Park', 'Once a month, one dish each, long tables, no speeches. Need two people to haul tables and someone to keep the sign-up sheet honest.', 'food', 'idea', 'local', 'neighborhood', 33.751250, -84.357428, null, now() - interval '22 days 11 hours', now() - interval '21 days'),
  ('ea100000-0000-4000-8000-000000000072', 'e1000000-0000-4000-8000-000000000192', 'Sunday morning tai chi at the Beltline at Krog', 'Slow, outdoors, free. A retired instructor leads; we need a backup leader and someone to bring the speaker.', 'fitness', 'active', 'local', 'neighborhood', null, null, '/photos/park-cleanup.jpg', now() - interval '6 days 6 hours', now() - interval '5 days')
